# AreaChart

## Overview

The AreaChart component is a complete area chart visualization that composes ChartHeader, ChartLegend, DataDisplay, AreaGroup, and ChartFooter. It supports three stacking modes (stacked, layered, fullHeight), animated entry and data morphing, broken Y-axis, interactive hover with a cursor-following badge, and an optional DataDisplay block that updates dynamically on series hover.

All tokens come from the CSS cascade — DataVis palette tokens via `generateDataVisCSS`, surface and typography tokens via `useBrandCSSNew`. No runtime JS token resolver.

**Figma reference**: [DataVis-Components — Node 174:3147](https://www.figma.com/design/uA5ExvS0cNXbDEKzT9Rnrt/DataVis-Components?node-id=174-3147)

## Architecture

```
AreaChart
├── ChartHeader (optional, chartHeader=true)
│   ├── ChartTitle
│   └── ChartSubtitle
├── ChartLegend (optional, chartLegend=true)
│   └── ChartKey[] (one per series, type="circle")
├── DataDisplay (optional, dataDisplay=true)
│   ├── mainLabel
│   ├── DataHead (DataLead + SupportingData + SupportingLabel)
│   └── Badge (BadgeConfig.value, BadgeConfig.appearance)
├── AreaGroup
│   ├── YAxis (optional)
│   ├── SVG → stacked/layered/fullHeight area paths
│   └── XAxis (optional)
└── ChartFooter (optional, chartFooter=true)
    └── annotation slots
```

## Import

```tsx
import { AreaChart } from '@oneui/datavis/components/charts/AreaChart';
import type {
  AreaChartProps,
  AreaGroupConfig,
  DataDisplayConfig,
  AreaGroupData,
  AreaSeriesData,
  AreaCurveStyle,
  AreaStackingType,
  AreaSeriesHoverData,
  ChartSeriesDataPoint,
  ChartLegendItem,
  AccessibilityConfig,
  DataHeadConfig,
  BadgeConfig,
} from '@oneui/datavis/components/charts/AreaChart';
```

## Data Formats

### Canonical Format (Recommended)

```typescript
import type { ChartSeriesDataPoint } from '@oneui/datavis';

const data: ChartSeriesDataPoint[] = [
  { category: 'Jan', series: 'Revenue', value: 100 },
  { category: 'Jan', series: 'Expenses', value: 80 },
  { category: 'Feb', series: 'Revenue', value: 120 },
  { category: 'Feb', series: 'Expenses', value: 85 },
];
```

### Legacy Format (Still Supported)

```typescript
const data: AreaGroupData = {
  categories: ['Jan', 'Feb', 'Mar'],
  series: [
    { name: 'Revenue', values: [100, 120, 115] },
    { name: 'Expenses', values: [80, 85, 90] },
  ],
};
```

> **Migration**: The component normalizes both formats internally. Legacy format logs a deprecation warning in development.

## Props Interface

```typescript
/** Slot-specific config passed to ChartHeader */
type ChartHeaderConfig = Pick<
  ChartHeaderProps,
  'chartTitleValue' | 'chartSubtitleValue' | 'title' | 'subtitle'
>;

/** Slot-specific config passed to ChartLegend */
interface ChartLegendConfig {
  items?: ChartLegendItem[];
}

/** Slot-specific config for the AreaGroup child */
interface AreaGroupConfig {
  yAxis?: boolean;
  xAxis?: boolean;
  curveStyle?: AreaCurveStyle;
  valueFormat?: ValueFormatConfig;
  hoverBadge?: boolean;
  controlledHoverBadge?: boolean;
  onSeriesHover?: (data: AreaSeriesHoverData | null) => void;
  onSeriesClick?: (data: AreaSeriesHoverData) => void;
  hoveredSeriesIndex?: number | null;
  yAxisConfig?: YAxisConfig;
  xAxisConfig?: XAxisConfig;
  hoverBadgeConfig?: HoverBadgeConfig;
  dataSort?: DataSortOrder;
  animated?: boolean;
  areaStackingType?: AreaStackingType;
}

/** Slot-specific config for the DataDisplay child.
 * When mode="hover", mainLabelValue, dataHead.dataLeadValue, and
 * badgeConfig.value update dynamically on area hover. */
interface DataDisplayConfig {
  // Chart-specific behaviour
  mode?: 'static' | 'hover';
  formatHoverLeadValue?: (seriesTotal: number, seriesName?: string) => string;
  formatHoverBadgeValue?: (seriesTotal: number, seriesName?: string) => string;

  // DataDisplay Layer 2 props (mirrored)
  mainLabelValue?: string;
  alignment?: 'Left' | 'Center';
  rightBadgeWrapper?: boolean;
  badgeTop?: boolean;
  badgeBottom?: boolean;
  showBadge?: boolean;
  supportingBadgeLabel?: boolean;
  supportingBadgeLabelValue?: string;
  size?: 'XS' | 'S' | 'M' | 'L' | 'XL';

  // DataDisplay Layer 3 configs (forwarded)
  dataHead?: DataHeadConfig;
  badgeConfig?: BadgeConfig;
}

/** Slot-specific config passed to ChartFooter */
type ChartFooterConfig = Pick<
  ChartFooterProps,
  'annotationLeft' | 'annotationLeftValue' | 'annotationRight' | 'annotationRightValue'
>;

interface AreaChartProps {
  data: ChartSeriesDataPoint[] | AreaGroupData;
  seriesOrder?: string[];
  width?: number | string;
  height?: number | string;
  /** Stretch chart to 100% of parent width (takes priority over width) */
  fullWidth?: boolean;
  chartHeader?: boolean;
  chartFooter?: boolean;
  chartLegend?: boolean;
  dataDisplay?: boolean;
  interactive?: boolean;
  animated?: boolean;
  chartHeaderConfig?: ChartHeaderConfig;
  chartLegendConfig?: ChartLegendConfig;
  dataDisplayConfig?: DataDisplayConfig;
  areaGroupConfig?: AreaGroupConfig;
  chartFooterConfig?: ChartFooterConfig;
  accessibility?: AccessibilityConfig;
}
```

